const text = $input.first().json.text;

if (!text || !text.trim()) {
  throw new Error("Document text is empty");
}

const lines = text
  .split(/\r?\n/)
  .map(line => line.trim())
  .filter(Boolean);

const documentTitle = lines[0];
const chunks = [];

let heading = null;
let paragraphs = [];

function saveChunk() {
  if (!heading || paragraphs.length === 0) return;

  chunks.push({
    title: heading,
    content: heading + "\n" + paragraphs.join(" ")
  });
}

for (const line of lines.slice(1)) {

  // Пропускаємо службову позначку документа
  if (/^SYNTHETIC DEMO DOCUMENT/i.test(line)) {
    continue;
  }

  // Тестові запитання не є корпоративними правилами
  if (/^Test questions:/i.test(line)) {
    break;
  }

  // Виявляємо короткі тематичні заголовки
  const isHeading =
    /^[A-Z][a-z]/.test(line) &&
    line.length < 65 &&
    line.split(/\s+/).length <= 8 &&
    !/[.!?:;]$/.test(line);

  if (isHeading) {
    saveChunk();
    heading = line;
    paragraphs = [];
  } else if (heading) {
    paragraphs.push(line);
  }
}

saveChunk();

return chunks.map((chunk, index) => ({
  json: {
    source: documentTitle,
    chunk_index: index,
    title: chunk.title,
    content: chunk.content,
    character_count: chunk.content.length
  }
}));

