const chunks = $('Split Document into Chunks')
  .all()
  .map(item => item.json);

const embeddings = $input.all()
  .map(item => item.json);

// Перевіряємо кількість фрагментів і векторів
if (chunks.length !== embeddings.length) {
  throw new Error("Chunks and embeddings count mismatch");
}

return chunks.map((chunk, index) => {

  const vector = embeddings[index].embedding.values;

  // Перевіряємо розмірність вектора

if (!Array.isArray(vector)) {
  throw new Error(`Embedding ${index} is not an array`);
}

if (vector.length !== 768) {
  throw new Error(
    `Embedding ${index}: expected 768, received ${vector.length}`
  );
}


  return {
    json: {
      source_id: `fitlife-${chunk.chunk_index}`,
      title: chunk.title,
      content: chunk.content,
      chunk_index: chunk.chunk_index,
      embedding: vector,
      dimensions: vector.length
    }
  };
});

